import type { MemberPlan, RankId } from '../config/plan.ts';

export type PlanCounts = Record<MemberPlan, number>;

export interface Prices {
  /** Activation production generated by one activation of each plan. */
  activation: PlanCounts;
  /** Monthly membership payment of each plan. */
  monthly: PlanCounts;
}

/** One direct Partner team ("leg"). */
export interface Leg {
  id: string;
  label: string;
  /** Rank of the direct Partner who heads this team. */
  rank: RankId;
  /** The direct Partner's own (personal) activations this month — drives Weekly Matching. */
  headActivations: PlanCounts;
  /** Activation volume produced by everyone else in the team this month. */
  otherActivationVolume: number;
  /** Monthly membership payments received from the whole team this month. */
  recurringVolume: number;
}

export interface MonthInput {
  /** Members you personally activated this month (new, upgrades and reactivations). */
  personalActivations: PlanCounts;
  /** Direct members who keep paying their monthly membership. */
  personalPayingMembers: PlanCounts;
  /** Share (0–1) of activations that are first-ever activations (Builders Base Volume). */
  newMemberShare: number;
  /** Quality of Business Index, 0–1. */
  qbi: number;
  /** Share of weeks (0–1) the Weekly Matching Bonus qualifies, or 'auto' to estimate from even weekly production. */
  matchingWeeks: number | 'auto';
  /** Minimum Activations Requirement met through a longer window (90/180/365 days). */
  minActivationsLongWindow: boolean;
  legs: Leg[];
}

/**
 * One Partner in your organization, with the Partners they sponsored below them.
 * Ranks aren't entered: they're computed from each Partner's own subtree.
 */
export interface PartnerNode {
  id: string;
  name: string;
  /** This Partner's own activations this month. */
  activations: PlanCounts;
  /** This Partner's direct Members who pay their monthly membership. */
  payingMembers: PlanCounts;
  /** Optional: activation volume of people below this Partner who aren't listed one by one. */
  restActivationVolume: number;
  /** Optional: monthly payments of people below this Partner who aren't listed one by one. */
  restRecurringVolume: number;
  /**
   * The Partner is also a Member (a Partner-Member). Their membership is their sponsor's
   * production: a new activation if it started this month, otherwise a paying member.
   */
  membership?: { plan: MemberPlan; since: string } | null;
  children: PartnerNode[];
}

export type ActivationKind = 'new' | 'upgrade' | 'reactivation';

/** One activation you made personally this month. */
export interface ActivationEntry {
  id: string;
  /** ISO date (yyyy-mm-dd). */
  date: string;
  plan: MemberPlan;
  /** Only first-ever activations ("new") count toward Builders Base Volume. */
  kind: ActivationKind;
}

/** Your earlier activity, as plain numbers: enough for the Minimum Activations windows and QBI. */
export interface ActivityHistory {
  /** Your activations 1–2 months ago (with this month: the 90-day window). */
  months1to2: PlanCounts;
  /** 3–5 months ago (completes the 180-day window). */
  months3to5: PlanCounts;
  /** 6–11 months ago (completes the 365-day window). */
  months6to11: PlanCounts;
  /** New Classic and Premium members your Builders Base activated in the last 3 months… */
  qbiNew: number;
  /** …and how many of them are still paying. */
  qbiPaying: number;
}

/**
 * Structure as the user enters it. Everything the monthly calculation needs beyond this
 * (activation counts, first-ever share, QBI, Weekly Matching weeks, Minimum Activations)
 * is derived from it — see toMonthInput.
 */
export interface BusinessMonth {
  activationLog: ActivationEntry[];
  personalPayingMembers: PlanCounts;
  history: ActivityHistory;
  team: PartnerNode[];
}

export interface CalcProfile {
  isMember: boolean;
  isPartner: boolean;
  memberPlan: MemberPlan;
  /** Partner renewal is paid and current. */
  renewalCurrent: boolean;
  /** This month is the Partner's first full calendar month (Fast Start window). */
  fastStartMonth: boolean;
}

export type IncomeKey = 'dab' | 'mab' | 'matching' | 'tlb' | 'recurring' | 'bbb' | 'fastStart';
export const INCOME_KEYS: IncomeKey[] = ['dab', 'mab', 'matching', 'tlb', 'recurring', 'bbb', 'fastStart'];

/** A translatable explanation: an i18n key with values to interpolate. */
export interface Note {
  key: string;
  params?: Record<string, string | number>;
  tone?: 'info' | 'good' | 'warn';
}

export interface IncomeLine {
  key: IncomeKey;
  amount: number;
  notes: Note[];
}

export interface RankGap {
  rankId: RankId;
  qpRequired: number;
  qpCounted: number;
  legCapAmount: number;
  cappedLegIds: string[];
  tavRequired: number;
  tav: number;
}

export interface MonthResult {
  production: {
    personalActivation: number;
    personalRecurring: number;
    directProduction: number;
    tav: number;
    qp: number;
    rqp: number;
    bbv: number;
  };
  qpRank: RankId;
  paidRank: RankId;
  tlbStatus: 'full' | 'partial' | 'none';
  nextRank: RankGap | null;
  income: Record<IncomeKey, number>;
  lines: IncomeLine[];
  costs: { renewal: number; membership: number; membershipWaiver: number; total: number };
  gross: number;
  net: number;
  conditions: {
    renewalCurrent: boolean;
    minActivations: { required: boolean; met: boolean };
    membershipFree: boolean;
    fastStart: boolean;
    superBbb: boolean;
    eligible: boolean;
  };
  notes: Note[];
}
